func NewTodoSubject(svc DefaultTodoService) TodoSubject { return TodoSubject{svc: svc} }

// Table implements notify.Subjects.
func (s TodoSubject) Table() string { return "todo" }

// Audience implements notify.Subjects.
func (s TodoSubject) Audience(ctx context.Context, n *notify.Notification, id uuid.UUID) ([]uuid.UUID, error) {
	row, err := s.svc.repo.Get(ctx, id, readopt.WithoutOwnerScope())
	if err != nil {
		return nil, err
	}
	return s.svc.contract.Notify.NotifyWho(ctx, n, row)
}

// NotifyAboutTodo names the row an announcement is about.
//
// Use it rather than building the value by hand: the table and the join are
// written here from the schema, so nothing a request carries reaches a
// statement.
func NotifyAboutTodo(id uuid.UUID) notify.Subject {
	return notify.Subject{
		Table:     "todo",
		LinkTable: "todo_notification",
		Column:    "todo_id",
		ID:        id,
	}
}

// AnnounceTodo builds the announcement, asking this resource's own NotifyAt
// when it is due.
//
// One call rather than three lines, because the middle one is the one to
// forget: an announcement written without asking NotifyAt is due now, and a
// draft would go out the moment somebody saved it.
func AnnounceTodo(rules TodoNotify, row *model.Todo, kind string) notify.Announcement {
	at, due := rules.NotifyAt(row, kind)
	return notify.Announcement{
		Kind:    kind,
		Subject: NotifyAboutTodo(row.ID),
		At:      at,
		Due:     due,
	}
}

// readFilter combines the caller's filter with whatever the read hook narrows
// to.
//
// Nested rather than merged, because the two are combined with AND: a caller
// whose own filter is an OR cannot widen its way out of the one the service
// added.
func (s DefaultTodoService) readFilter(ctx context.Context, claims tenancy.Claims, asked model.TodoFilter) (model.TodoFilter, error) {
	if s.contract.Hooks.Read.Narrow == nil {
		return asked, nil
	}

	narrowed, err := s.contract.Hooks.Read.Narrow(ctx, caller(claims))
	if err != nil {
		return asked, err
	}
	if narrowed == nil {
		return asked, nil
	}

	return model.TodoFilter{NestedFilters: []model.TodoFilter{*narrowed, asked}}, nil
}

// readRows runs the read hook over what a read is about to answer with.
func (s DefaultTodoService) readRows(ctx context.Context, claims tenancy.Claims, rows []*model.Todo) error {
	if s.contract.Hooks.Read.Rows == nil {
		return nil
	}
	return s.contract.Hooks.Read.Rows(ctx, caller(claims), rows)
}

// List implements TodoService.
func (s DefaultTodoService) List(ctx context.Context, r Request[struct{}, TodoListQuery, struct{}]) (*TodoListResponse, error) {
	page := model.TodoPage{Limit: r.Query.Limit, Offset: r.Query.Offset}
	asked := model.NewTodoFilter()
	filter, err := s.readFilter(ctx, r.Claims, asked)
	if err != nil {
		return nil, err
	}

	rows, total, err := s.repo.List(ctx, filter, page)
	if err != nil {
		return nil, err
	}
	if err := s.readRows(ctx, r.Claims, rows); err != nil {
		return nil, err
	}

	return &TodoListResponse{
		Data:       rows,
		Pagination: Pagination{Offset: page.Offset, Limit: page.Limit, Total: total},
	}, nil
}

