// Get implements TodoService.
func (s DefaultTodoService) Get(ctx context.Context, r Request[TodoGetPath, struct{}, struct{}]) (*model.Todo, error) {
	row, err := s.repo.Get(ctx, r.Path.ID)
	if err != nil {
		return nil, err
	}

	// Not narrowed: Get fetches by primary key, and there is no filter to add a
	// condition to. A rule about whether this caller may have this row belongs in
	// Rows, which is handed it.
	if err := s.readRows(ctx, r.Claims, []*model.Todo{row}); err != nil {
		return nil, err
	}
	return row, nil
}

