// Versions implements TodoService.
func (s DefaultTodoService) Versions(ctx context.Context, r Request[TodoVersionsPath, struct{}, struct{}]) (*TodoListResponse, error) {
	if _, err := s.repo.Get(ctx, r.Path.ID); err != nil {
		return nil, err
	}

	versions, err := s.repo.ListSnapshots(ctx, r.Path.ID)
	if err != nil {
		return nil, err
	}
	if err := s.readRows(ctx, r.Claims, versions); err != nil {
		return nil, err
	}

	// A history is not paged: the whole of it comes back, and the pagination block
	// says exactly that rather than describing a page nobody asked for.
	return &TodoListResponse{
		Data:       versions,
		Pagination: Pagination{Limit: len(versions), Total: int64(len(versions))},
	}, nil
}
